// Phase 15 -- safe access to experiment artifacts on disk.
//
// Two jobs the per-phase routes each did slightly differently (or not
// at all) before:
//
//  1. experiment ids are validated before they ever become part of a
//     file path. Express decodes %2F in route params, so an id like
//     "..%2F..%2Fsecret" used to reach `join(EXPERIMENTS_DIR, id)`
//     unchanged. Ids are generated by the dashboard as `exp-<base36>`
//     (or typed/loaded from the library), so a strict allow-list costs
//     nothing and closes that hole (Dashboard Spec Ch.71.17).
//
//  2. an artifact that exists but cannot be parsed (a run killed
//     mid-write) is reported as "corrupt" instead of throwing inside a
//     request handler and returning an HTML 500 page.
import { existsSync, readFileSync } from "fs";
import { fileURLToPath } from "url";
import { dirname, join } from "path";
import { sendInvalidRequest } from "./errors.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
// backend/src/ -> repo root
export const REPO_ROOT = join(__dirname, "..", "..");
export const EXPERIMENTS_DIR = join(REPO_ROOT, "experiments");

const EXPERIMENT_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/;

export function isValidExperimentId(id) {
  return typeof id === "string" && EXPERIMENT_ID_PATTERN.test(id) && !id.includes("..");
}

/** Express `router.param` handler: reject malformed ids with a 400. */
export function validateExperimentIdParam(_req, res, next, id) {
  if (!isValidExperimentId(id)) {
    return sendInvalidRequest(res, "That experiment id is not valid.");
  }
  next();
}

export function artifactPath(experimentId, filename) {
  return join(EXPERIMENTS_DIR, experimentId, filename);
}

/**
 * @returns {{state: "missing"} | {state: "corrupt"} | {state: "ok", data: any}}
 */
export function readArtifact(experimentId, filename) {
  const path = artifactPath(experimentId, filename);
  if (!existsSync(path)) return { state: "missing" };
  try {
    return { state: "ok", data: JSON.parse(readFileSync(path, "utf-8")) };
  } catch {
    return { state: "corrupt" };
  }
}
